 const actions=el('div','hr21-actions');btn(actions,'Apply dated edits',()=>{const candidate=engine.settings;for(const d of drafts){if(d.rows.some(r=>!String(r.a.value).trim()||!String(r.c.value).trim()))return status('Drawing unchanged: each dated frame needs a year and visual tendency.');candidate.waterFrames[d.id]=d.rows.map(r=>({yearBce:Number(r.a.value),index:Number(r.c.value)}));}changed(candidate,'Dated drawing edits applied. The source evidence is unchanged.');});
